package com.portfolio.hireflow.interview.service;
import java.time.Instant;import java.util.*;import org.springframework.data.domain.PageRequest;import org.springframework.data.jpa.domain.Specification;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import com.portfolio.hireflow.auth.entity.AppUser;import com.portfolio.hireflow.auth.repository.AppUserRepository;import com.portfolio.hireflow.common.exception.UnauthorizedException;import com.portfolio.hireflow.interview.dto.CompanyCalendarEventResponse;import com.portfolio.hireflow.interview.entity.*;import com.portfolio.hireflow.interview.repository.*;
@Service @Transactional(readOnly=true)
public class CompanyCalendarService{
 private final InterviewRepository interviews;private final InterviewTimeSlotRepository slots;private final AppUserRepository users;
 public CompanyCalendarService(InterviewRepository interviews,InterviewTimeSlotRepository slots,AppUserRepository users){this.interviews=interviews;this.slots=slots;this.users=users;}
 public List<CompanyCalendarEventResponse> events(String email,Instant from,Instant to){AppUser actor=users.findByEmailIgnoreCase(email).orElseThrow(()->new UnauthorizedException("登入狀態無效"));Specification<Interview> spec=(r,q,b)->b.and(b.greaterThanOrEqualTo(r.get("startsAt"),from),b.lessThan(r.get("startsAt"),to));if(interviewerOnly(actor))spec=spec.and((r,q,b)->{q.distinct(true);return b.equal(r.join("interviewers").get("id"),actor.getId());});else if(!all(actor))spec=spec.and((r,q,b)->b.equal(r.get("application").get("jobOpening").get("department").get("id"),actor.getDepartment().getId()));List<CompanyCalendarEventResponse> result=new ArrayList<>(interviews.findAll(spec,PageRequest.of(0,500)).stream().map(i->new CompanyCalendarEventResponse("interview-"+i.getId(),"CONFIRMED",i.getApplication().getId(),i.getApplication().getCandidate().getFullName(),i.getApplication().getJobOpening().getJobTitle(),i.getApplication().getJobOpening().getDepartment().getName(),i.getStartsAt(),i.getEndsAt(),i.getFormat(),i.getLocation(),i.getStatus().name())).toList());slots.findByStartsAtGreaterThanEqualAndStartsAtLessThanOrderByStartsAt(from,to).stream().filter(s->s.getStatus()==InterviewTimeSlotStatus.AVAILABLE).filter(s->all(actor)||(interviewerOnly(actor)?s.getInterviewers().stream().anyMatch(u->u.getId().equals(actor.getId())):actor.getDepartment()!=null&&actor.getDepartment().getId().equals(s.getDepartment().getId()))).map(s->new CompanyCalendarEventResponse("slot-"+s.getId(),"PROPOSED",s.getApplication().getId(),s.getApplication().getCandidate().getFullName(),s.getApplication().getJobOpening().getJobTitle(),s.getDepartment().getName(),s.getStartsAt(),s.getEndsAt(),s.getFormat(),s.getLocation(),s.getStatus().name())).forEach(result::add);result.sort(Comparator.comparing(CompanyCalendarEventResponse::startsAt));return result;}
 private boolean all(AppUser a){return has(a,"HR")||has(a,"ADMIN");}private boolean interviewerOnly(AppUser a){return has(a,"INTERVIEWER")&&!all(a)&&!has(a,"HIRING_MANAGER");}private boolean has(AppUser a,String r){return a.getRoles().stream().anyMatch(x->x.getCode().equals(r));}
}
